def f(Ain):
    A=np.array(Ain); H,W=A.shape
    fc=A[0,0]
    # frame width: max w s.t. column 0 all fc and there's a closed right border: try each w with both side cols all fc
    ws=[w for w in range(2,W//2+1) if all(A[r,0]==fc and A[r,w-1]==fc for r in range(H))]
