import numpy as np, json
D1=np.array(G['Demo pair 1 input']); D2=np.array(G['Demo pair 2 input'])
E1=np.array(G['Demo pair 1 output']); E2=np.array(G['Demo pair 2 output'])
def solve(Ain):
    A=np.array(Ain); H,W=A.shape; fc=int(A[0,0])
    end=max(c for c in range(W) if all(int(A[r,c])==fc for r in range(H)))
    holes=[]; hseen=np.zeros((H,end+1),bool)
    for r in range(H):
        for c in range(end+1):
            if int(A[r,c])==0 and not hseen[r,c]:
                st=[(r,c)]; comp=set()
                while st:
                    x,y=st.pop()
                    if not(0<=x<H and 0<=y<=end) or hseen[x,y] or int(A[x,y])!=0: continue
                    hseen[x,y]=True; comp.add((x,y)); st+=[(x+1,y),(x-1,y),(x,y+1),(x,y-1)]
                mr=min(a for a,b in comp); mc=min(b for a,b in comp)
                holes.append({'norm':tuple(sorted((a-mr,b-mc) for a,b in comp)),'mr':mr,'mc':mc})
    shapes=[]; sseen=np.zeros((H,W),bool)
    for r in range(H):
        for c in range(W):
            if int(A[r,c]) in (0,fc) or sseen[r,c]: continue
            st=[(r,c)]; comp=[]
            while st:
                x,y=st.pop()
                if not(0<=x<H and 0<=y<W) or sseen[x,y] or int(A[x,y])!=int(A[r,c]): continue
                sseen[x,y]=True; comp.append((x,y)); st+=[(x+1,y),(x-1,y),(x,y+1),(x,y-1)]
            rs=[a for a,b in comp]; cs_=[b for a,b in comp]
            shapes.append({'v':int(A[comp[0][0],comp[0][1]]),
                           'norm':tuple(sorted((a-min(rs),b-min(cs_)) for a,b in comp))})
    out=np.full((H,end+1),fc,dtype=int)
    for s in shapes:
        for h in holes:
            if s['norm']==h['norm']:
                for dr,dc in s['norm']:
                    out[h['mr']+dr,h['mc']+dc]=s['v']
                break
    return out.tolist()
print('d1', np.array_equal(np.array(solve(D1)),E1), 'd2', np.array_equal(np.array(solve(D2)),E2))
